import heapq


def order_tasks(dependencies):
    prerequisites = {}
    nodes = set(dependencies)

    for task, deps in dependencies.items():
        unique_deps = set(deps)
        prerequisites[task] = unique_deps
        nodes.update(unique_deps)

    for node in nodes:
        prerequisites.setdefault(node, set())

    dependents = {node: set() for node in nodes}
    indegree = {node: len(prerequisites[node]) for node in nodes}

    for task, deps in prerequisites.items():
        for dependency in deps:
            dependents[dependency].add(task)

    ready = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)

    ordered = []
    while ready:
        node = heapq.heappop(ready)
        ordered.append(node)

        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(ordered) != len(nodes):
        raise ValueError("cycle detected")

    return ordered

import unittest

from graph import order_tasks


class TestGraphRegression(unittest.TestCase):
    def test_empty_mapping(self):
        self.assertEqual(order_tasks({}), [])

    def test_prerequisite_only_node_is_included(self):
        self.assertEqual(order_tasks({"build": ["compile"]}), ["compile", "build"])

    def test_repeated_prerequisites_count_once(self):
        self.assertEqual(
            order_tasks({"build": ["compile", "compile"], "compile": []}),
            ["compile", "build"],
        )

    def test_lexicographically_smallest_currently_ready_node(self):
        self.assertEqual(
            order_tasks({"z": [], "a": ["b"], "b": []}),
            ["b", "a", "z"],
        )

    def test_self_cycle_raises(self):
        with self.assertRaises(ValueError):
            order_tasks({"a": ["a"]})

    def test_multi_node_cycle_raises(self):
        with self.assertRaises(ValueError):
            order_tasks({"a": ["b"], "b": ["c"], "c": ["a"]})

    def test_input_is_not_mutated(self):
        dependencies = {
            "build": ["test", "test"],
            "test": ["lint"],
            "lint": [],
        }
        original = {task: list(deps) for task, deps in dependencies.items()}

        order_tasks(dependencies)

        self.assertEqual(dependencies, original)


if __name__ == "__main__":
    unittest.main()

